const ZONESDIR = process.env.ZONES_DIR || (fs.existsSync(path.join(HERE, 'radar_tools', 'zones')) ? path.join(HERE, 'radar_tools', 'zones') : path.join(HERE, '..', 'zones'));
const LWC = fs.readFileSync(path.join(HERE, 'lwc.js'), 'utf8');
