const Q15 = 900000, H1 = 3600000;
let pass = 0, fail = 0;
function ok(c, m) { if (c) pass++; else { fail++; console.log('FAIL: ' + m); } }
function eq(a, b, m) { ok(JSON.stringify(a) === JSON.stringify(b), m + ' | got ' + JSON.stringify(a) + ' want ' + JSON.stringify(b)); }
const sha = b => crypto.createHash('sha256').update(b).digest('hex');
function block(html) { const a = html.indexOf('/* item 52c — depth overlay'), z = html.indexOf('/* end item 52c */'); return a < 0 || z < 0 ? null : html.slice(a, z + '/* end item 52c */'.length); }
const SNIP = block(RADAR), SNIP52C = fs.readFileSync(path.join(FX, 'base52c-block.js'), 'utf8'), SNIP52G = fs.readFileSync(path.join(FX, 'base52g-block.js'), 'utf8'), SNIP52H = fs.readFileSync(path.join(FX, 'base52h-block.js'), 'utf8'), SNIP52I = fs.readFileSync(path.join(FX, 'base52i-block.js'), 'utf8'), SNIP52N = fs.readFileSync(path.join(FX, 'base52n-block.js'), 'utf8'), SNIP52J = fs.readFileSync(path.join(FX, 'base52j-block.js'), 'utf8');   /* base52h-block.js = the block of radar.html 4e3062bd (item 52h) */   /* fixtures/base52g-block.js = the 52c/52g block of radar.html e66b346c (the 52g base), for the item 52h identity checks */   /* fixtures/base52c-block.js = the 52c block of radar.html dd79517e, for the byte-identity checks against 52c */

/* ---------- synthetic rolling tree ---------- */
function slotPath(venue, ms) { const d = new Date(ms), iso = d.toISOString(); return 'book/' + venue + '/' + iso.slice(0, 10) + '/' + iso.slice(11, 13) + iso.slice(14, 16) + '.json.gz'; }
function rawBook(venue, mid, o) {
  o = o || {}; const n = o.levels || 200, step = o.step || 0.0005, sz = o.size || 10, dec = o.dec == null ? 2 : o.dec, bids = [], asks = [];
  for (let i = 1; i <= n; i++) { bids.push([(mid * (1 - step * i)).toFixed(dec), String(sz), venue === 'kraken' ? 1 : 1]); asks.push([(mid * (1 + step * i)).toFixed(dec), String(sz), 1]); }
  (o.asks || []).forEach(x => asks.push([String(x[0]), String(x[1]), 1])); (o.bids || []).forEach(x => bids.push([String(x[0]), String(x[1]), 1]));
  return venue === 'kraken' ? { bids, asks } : { bids, asks, sequence: 1, time: new Date().toISOString() };
}
function mkRec(venue, pair, anchor, tick, slotMs, raw, o) {
  o = o || {}; const grid = B.makeGrid(anchor, tick, '2026-10', venue, pair, o.version), req = new Date(slotMs + 6 * 60000).toISOString(), rcv = new Date(slotMs + 6 * 60000 + 800).toISOString();
  const ctx = { pair, count: o.count || 500, requestStartUtc: req, receivedAtUtc: rcv }, book = venue === 'kraken' ? B.parseKraken(raw, ctx) : B.parseCoinbase(raw, ctx);
  return B.buildRecord(book, grid, { intervals: o.intervals || [], maxTerms: 0 });
}
function mkBatch(recs, venue, pair, tick, slotMs) { const sc = {}; sc[venue + '|' + pair] = C.scaleFor(tick, 1e-6, 'USD'); const enc = C.encodeBatch(recs, sc, { venue, slot: new Date(slotMs).toISOString() }); return zlib.gzipSync(Buffer.from(JSON.stringify(enc.batch))); }
/* tree: { files: Map(path -> Buffer), table: [], grids: {}, observedAt } ; finish() writes cadence/grids/registry. hashMode: 'all' | 'latest' | 'none' */
function newTree() { return { files: new Map(), table: [], grids: {}, observedAt: null, paths: [] }; }
function addBatch(t, venue, slotMs, buf) { const p = slotPath(venue, slotMs); t.files.set(p, buf); t.paths.push([p, slotMs]); if (!t.observedAt || slotMs > t.observedAt) t.observedAt = slotMs; }
function finish(t, hashMode, opts) {
  opts = opts || {};
  const cad = Buffer.from(JSON.stringify({ version: 'v', updatedAt: 'x', table: t.table })), grd = Buffer.from(JSON.stringify({ updatedAt: 'x', grids: t.grids }));
  t.files.set('book/cadence.json', cad); t.files.set('book/grids.json', grd);
  const hashes = { 'book/cadence.json': opts.badCadenceHash ? 'deadbeef' : sha(cad), 'book/grids.json': sha(grd) };
  const lastBy = {}; t.paths.forEach(([p, ms]) => { const v = p.split('/')[1]; if (!lastBy[v] || ms > lastBy[v][1]) lastBy[v] = [p, ms]; });
  t.paths.forEach(([p, ms]) => { const v = p.split('/')[1]; if (hashMode === 'all' || (hashMode === 'latest' && lastBy[v][0] === p)) hashes[p] = sha(t.files.get(p)); });
  t.files.set('meta/datasets.json', Buffer.from(JSON.stringify({ schema: 1, datasets: { book: { hashes, observedAt: new Date(t.observedAt).toISOString(), version: new Date(t.observedAt).toISOString(), codec: 1, grid: 2, schema: 2 } } })));
  return t;
}
function cadEntry(venue, pair, tier, fromMs) { return { venue, pair, tier, cadenceMs: tier === 'q15' ? Q15 : H1, reasons: [], fromMs, toMs: null }; }
const NOW1 = Date.parse('2026-10-14T06:10:00Z'), T0 = Date.parse('2026-10-14T00:00:00Z');
/* scenario: venue/pair q15, 16 slots 02:15..06:00; mid drifts 100.00 -> 100.75 (grid anchor stays 100); one ask wall at 103 in every slot */
function scenario(o) {
  o = o || {}; const venue = o.venue || 'kraken', pair = o.pair || 'TST/USD', t = o.tree || newTree(), n = o.slots == null ? 16 : o.slots, wall = o.wallPx || 103;
  t.table.push(cadEntry(venue, pair, 'q15', T0)); t.grids[venue + '|' + pair] = { anchor: 100, tick: 0.01, period: '2026-10' };
  for (let i = 0; i < n; i++) {
    const slot = NOW1 - 3 * 60000 - (15 - i) * Q15 + (o.shift || 0); const s = Math.floor(slot / Q15) * Q15, mid = 100 + 0.05 * i;
    const raw = rawBook(venue, mid, { size: o.size || 10, levels: o.levels, step: o.step, count: o.count, asks: o.askFn ? o.askFn(i) : [[wall, o.wallSize == null ? 20000 : o.wallSize]], bids: o.bidWall ? [[o.bidWall, 20000]] : [] });
    const rec = mkRec(venue, pair, 100, 0.01, s, raw, { count: o.count, intervals: o.intervals });
    addBatch(t, venue, s, mkBatch([rec], venue, pair, 0.01, s));
  }
  return t;
}

/* ---------- harness ---------- */

