/* ---------- 52g harness: synthetic candles, params, venues ---------- */
const DEFAULT_PARAMS = () => ({ version: 1, status: 'uncalibrated', clustering: { name: 'A', baselineMethod: 'median', neighborhoodPct: 4, seedMinConcentration: 3, extendMinConcentration: 1.5, maxGapPct: 1, maxZoneWidthPct: 5 }, cutoffs: { concentration: null, material: null }, staleMultiplier: 1.5, frozenBy: null, date: null, note: 'cutoffs are set only by an Astra ruling on a calibration bundle' });   /* item 52r: the diagnostic-mode fixture is an inline copy of the pre-freeze file, independent of the shipped data/book/sellzone-params.json (now frozen) */
const FROZEN = (c, m) => Object.assign(DEFAULT_PARAMS(), { status: 'frozen', cutoffs: { concentration: c, material: m }, frozenBy: 'Astra ruling (test fixture)', date: '2026-10-20' });
/* candle sets: valid hours of the 168-hour window [H-168h, H); Kraken rows carry VWAP, Coinbase rows carry low/high/close */
